/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  phases([[0,14],[14,50],[50,66],[66,80]]);
  v.xO = lin([[0,0],[2,1]]) * out; v.t1 = p >= 6 ? 1 : 0; v.t0 = 1 - v.t1;
  v.sO = lin([[13,0],[15,1]]) * out;
  v.sp3 = p >= 18 ? out : 0; v.sp0 = p >= 28 ? out : 0; v.sp1 = p >= 38 ? out : 0; v.sp2 = p >= 48 ? out : 0;
  for (var i = 0; i < 5; i++) v['mn'+i] = lin([[20 + i * 1.6, 0],[21.5 + i * 1.6, 1]]) * out;
  for (var i = 0; i < 10; i++) v['fu'+i] = lin([[30 + i * 0.8, 0],[31.2 + i * 0.8, 1]]) * out;
  v.fcut = (p >= 32.4 && p < 53) ? out : 0; v.fsplit = p >= 53 ? out : 0;
  for (var i = 0; i < 15; i++) v['hg'+i] = lin([[40 + i * 0.5, 0],[41 + i * 0.5, 1]]) * out;
  v.holeD = (p >= 50 && p < 53) ? 1 : 0; v.hole = p >= 53 ? out : 0;
  v.trO = lin([[56,0],[60,1]]) * out; v.apL = lin([[53,0],[56,1]]) * out;
  v.dtO = lin([[66,0],[69,1]]) * out; v.dtT = 'translateY(' + lin([[66,12],[69,0]]).toFixed(1) + 'px)';

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
